L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RESOURCE_ETERNIUM"
L44_1 = "이면세계에서 발견되는 전략자원.\n소대 운용에 사용됩니다.\n주로  다이브, 월드맵 파견 임무, 미션 보상 등을 통해 획득할 수 있습니다."
