L45_1 = "이면세계와 업계의 정보를 정리한 보고서.\n월드맵 이벤트, 카운터케이스 열람 등에 사용됩니다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RESOURCE_DAILY_TICKET"
L46_1 = "모의작전 추가 입장에 필요한 티켓.\n매일 일정 수량을 상점에서 구매할 수 있으며,\n구매 횟수에 비례해 가격이 증가한다.\n구매 제한과 가격은 매일 자정에 초기화 된다."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
