L22_1 = "잉그리드가 가장 좋아하는 메뉴.\n한 잔만 마셔도 든든해져서 기운이 난다.\n일정 확률로 적성핵 혹은 특수적성핵을 획득합니다.\n해당 아이템은 이벤트 종료 이후 삭제됩니다."
