L3_1 = {}
L4_1 = "SI_ITEM_MISC_DESC_INTERIOR_MONTHLY_2022_02"
L5_1 = "브레멘 동물 전대의 한정판 캐릭터 가구. 오래된 골동품에 집착하는 낭만주의자 알프레드를 본떴다. 극장판에선 낡은 비행기 하나로 악당 프랑켄 장군의 비행사단에 맞서 싸우며 활약했다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_ITEM_MISC_DESC_INTERIOR_MONTHLY_2022_03"
L6_1 = "브레멘 동물전대의 한정판 캐릭터 가구. 작중 최고의 악당 프랑켄 장군의 사악한 모습을 본땄다. 극장판, 두근두근 새모이 작전에서 알프레드 남작에게 패배하며 다시금 복수를 위해 세력을 모으고 있다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_ITEM_MISC_DESC_INTERIOR_MONTHLY_2022_04"
L7_1 = "브레멘 동물전대의 한정판 캐릭터 가구. 작중 냉동 능력자라는 설정을 가진 안드레아스 소령을 모델로 제작된 빙수기계다. 동시 출시되었던 푹신푹신 안드레아스 여름용 젤베개는 판매 10분만에 매진되고 말았다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_ITEM_MISC_DESC_INTERIOR_MONTHLY_2022_05"
L8_1 = "브레멘 전대의 창설대원 프로기 중사를 구하기 위해 미래에서 넘어온 대 전자전 기술자.\n새모이 전쟁에서 프랑켄 군의 미사일 궤도가 바뀌며 원래대로라면 죽었어야 할 프로기 중사를 구출했다. 비주얼 리워크 버전이라는 제작사 측의 발표와 달리 노이즈와 함께 등장하며 스토리 반전이 이루어졌고 많은 시청자들을 놀라게 했다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
