L9_1 = "네크로노미코가 필살기를 쓸 때 나타나는 암흑 성전. 원작의 처형곡 완벽 재현. 로프는 한정 옵션이다."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
